/**
 * hairLettering.js — living hair-lettering effect (Stripey Bear)
 * Framework-agnostic. Mounts into any container element; cleans up fully.
 *
 * Requires three.js r128 (global THREE, or pass it in via config.THREE).
 *   HTML:  <script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
 *   React: import * as THREE from 'three';  // then pass { THREE } in config
 *
 * Usage:
 *   const handle = createHairLettering(el, { mode:'flow' });
 *   // later, on unmount / route change:
 *   handle.destroy();
 *
 * The artwork is embedded as a data URI by default (zero asset setup, no CORS).
 * To use a hosted image instead, pass config.imageUrl (must be same-origin or
 * CORS-enabled, since the effect reads its pixels).
 */

const EMBEDDED_IMAGE = "data:image/png;base64,";

// ---- default config (the settings locked in from the demo) ---------------
// Panel value  ->  config field
//   Motion: Flow           mode: 'flow'
//   Movement 8%            movement: 0.08
//   Hair length 1.64x      hairLength: 1.64
//   Density 100%           density: 1.0
//   Comb strength 27%      combStrength: 0.27
//   Comb size 100%         combSize: 1.0
//   Bounce 100%            bounce: 1.0
const DEFAULTS = {
  THREE: null,
  imageUrl: null,          // null → use the embedded artwork
  background: 'transparent', // 'transparent' | any CSS hex like '#0E0B0A'
  mode: 'flow',            // 'flow' | 'breeze'
  movement: 0.08,
  hairLength: 1.64,
  density: 1.0,
  combStrength: 0.27,
  combSize: 1.0,           // 0..1
  bounce: 1.0,             // 0..1
  hairs: 30000,            // strand count at density 1.0
  interactive: true,       // cursor comb on/off
  showCursorRing: false,   // dev affordance
  respectReducedMotion: true,
  pauseWhenOffscreen: true
};

export function createHairLettering(container, userConfig = {}) {
  const cfg = Object.assign({}, DEFAULTS, userConfig);
  const THREE = cfg.THREE || (typeof window !== 'undefined' ? window.THREE : null);
  if (!THREE) throw new Error('[hairLettering] three.js r128 not found. Include it globally or pass config.THREE.');
  if (!container) throw new Error('[hairLettering] a container element is required.');

  const SEGMENTS = 6;
  const COMB_K = 130, COMB_K_RELEASE = 22;
  let combZeta = 1.15 - cfg.bounce * 1.0;
  let combVel = 0;

  let disposed = false, raf = null, visible = true, built = false;
  let renderer, scene, camera, geo, mat, mesh, basePlane, baseTex, data;
  let ro = null, io = null, last = 0;
  let mTX = 0, mTY = 0, mOn = 0;

  const uniforms = {
    uTime:{value:0},
    uWind:{value: cfg.movement},
    uMode:{value: cfg.mode === 'flow' ? 1 : 0},
    uLen:{value: cfg.hairLength},
    uComb:{value: cfg.combStrength},
    uRadius:{value: 0.04 + cfg.combSize * 0.42},
    uMouse:{value: new THREE.Vector2(999,999)},
    uMouseOn:{value: 0}
  };

  if (cfg.respectReducedMotion && typeof matchMedia === 'function'
      && matchMedia('(prefers-reduced-motion: reduce)').matches) {
    uniforms.uWind.value = Math.min(uniforms.uWind.value, 0.03);
  }

  // ---- canvas + cursor ring --------------------------------------------
  const canvas = document.createElement('canvas');
  canvas.style.display = 'block';
  canvas.style.width = '100%';
  canvas.style.height = '100%';
  container.appendChild(canvas);

  let ring = null;
  if (cfg.showCursorRing) {
    ring = document.createElement('div');
    Object.assign(ring.style, {
      position:'fixed', left:'0', top:'0', border:'1.5px solid currentColor',
      borderRadius:'50%', transform:'translate(-50%,-50%)', pointerEvents:'none',
      opacity:'0', transition:'opacity .6s ease', zIndex:'5'
    });
    document.body.appendChild(ring);
  }

  // ---- shaders ---------------------------------------------------------
  const VERT = `
    precision highp float;
    attribute vec2 iRoot; attribute vec2 iDir;
    attribute float iLen; attribute float iWid; attribute vec3 iCol;
    attribute float iSeed; attribute float iPhase;
    uniform float uTime,uWind,uMode,uLen,uComb,uRadius;
    uniform vec2 uMouse; uniform float uMouseOn;
    varying vec3 vCol; varying float vT; varying float vSide;
    vec3 mod289(vec3 x){return x-floor(x*(1.0/289.0))*289.0;}
    vec2 mod289(vec2 x){return x-floor(x*(1.0/289.0))*289.0;}
    vec3 permute(vec3 x){return mod289(((x*34.0)+1.0)*x);}
    float snoise(vec2 v){
      const vec4 C=vec4(0.211324865405187,0.366025403784439,-0.577350269189626,0.024390243902439);
      vec2 i=floor(v+dot(v,C.yy)); vec2 x0=v-i+dot(i,C.xx);
      vec2 i1=(x0.x>x0.y)?vec2(1.0,0.0):vec2(0.0,1.0);
      vec4 x12=x0.xyxy+C.xxzz; x12.xy-=i1; i=mod289(i);
      vec3 p=permute(permute(i.y+vec3(0.0,i1.y,1.0))+i.x+vec3(0.0,i1.x,1.0));
      vec3 m=max(0.5-vec3(dot(x0,x0),dot(x12.xy,x12.xy),dot(x12.zw,x12.zw)),0.0);
      m=m*m; m=m*m;
      vec3 x=2.0*fract(p*C.www)-1.0; vec3 h=abs(x)-0.5; vec3 ox=floor(x+0.5); vec3 a0=x-ox;
      m*=1.79284291400159-0.85373472095314*(a0*a0+h*h);
      vec3 g; g.x=a0.x*x0.x+h.x*x0.y; g.yz=a0.yz*x12.xz+h.yz*x12.yw;
      return 130.0*dot(m,g);
    }
    void main(){
      float t = position.x; float side = position.y;
      vT = t; vSide = side; vCol = iCol;
      vec2 dir = normalize(iDir); vec2 nrm = vec2(-dir.y, dir.x);
      vec2 base = iRoot + dir * (t * iLen * uLen);
      float rest = snoise(iRoot*7.0 + iSeed) * 0.35;
      float nz = snoise(base*3.2 + vec2(uTime*0.18, uTime*0.12) + iSeed*0.15);
      float breeze = nz * pow(t,1.5);
      float wave = sin(iPhase*46.0 - uTime*2.4 + iSeed*0.4);
      float flow = wave * pow(t,1.25);
      float lateral = rest*pow(t,1.3)*0.6 + mix(breeze, breeze*0.4 + flow*1.1, uMode);
      lateral *= uWind * (iLen*uLen*3.2);
      vec2 pos = base + nrm * lateral;
      if(abs(uMouseOn) > 0.001){
        vec2 d = pos - uMouse; float dist = length(d); float R = uRadius;
        if(dist < R){ float f=(1.0-dist/R); pos += normalize(d)*f*f*uComb*uMouseOn*0.14*pow(t,1.4); }
      }
      float w = iWid * (1.0 - pow(t,1.4));
      pos += nrm * side * w;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(pos,0.0,1.0);
    }`;
  const FRAG = `
    precision highp float;
    varying vec3 vCol; varying float vT; varying float vSide;
    void main(){
      float edge = smoothstep(1.0, 0.35, abs(vSide));
      float tip  = smoothstep(1.0, 0.55, vT);
      float a = edge * mix(1.0, 0.65, vT) * (0.55+0.45*tip);
      vec3 c = vCol * (0.9 + 0.14*vT);
      // slight saturation boost so it pops like the bear artwork
      float lum = dot(c, vec3(0.299, 0.587, 0.114));
      c = mix(vec3(lum), c, 1.12);
      gl_FragColor = vec4(c, a*0.92);
    }`;

  // ---- image preprocessing (rest-orientation + arc-length fields) ------
  function boxBlur(src,W,H,r){
    const tmp=new Float32Array(src.length), out=new Float32Array(src.length);
    const norm=1/(2*r+1);
    for(let y=0;y<H;y++){ let acc=0;
      for(let x=-r;x<=r;x++) acc+=src[y*W+Math.min(W-1,Math.max(0,x))];
      for(let x=0;x<W;x++){ tmp[y*W+x]=acc*norm;
        const xo=x-r, xi=x+r+1;
        acc+=src[y*W+Math.min(W-1,Math.max(0,xi))]-src[y*W+Math.min(W-1,Math.max(0,xo))]; } }
    for(let x=0;x<W;x++){ let acc=0;
      for(let y=-r;y<=r;y++) acc+=tmp[Math.min(H-1,Math.max(0,y))*W+x];
      for(let y=0;y<H;y++){ out[y*W+x]=acc*norm;
        const yo=y-r, yi=y+r+1;
        acc+=tmp[Math.min(H-1,Math.max(0,yi))*W+x]-tmp[Math.min(H-1,Math.max(0,yo))*W+x]; } }
    return out;
  }
  function orangeClamp(r,g,b){
    const mx=Math.max(r,g,b), mn=Math.min(r,g,b);
    const sat = mx>0 ? (mx-mn)/mx : 0;
    if(sat < 0.30){ const L=Math.max(mx,0.28); return [Math.min(1,L), 0.56*L, 0.15*L]; }
    return [r,g,b];
  }
  function smooth01(x,a,b){ x=Math.min(1,Math.max(0,(x-a)/(b-a))); return x*x*(3-2*x); }

  function preprocess(img){
    const W=img.width, H=img.height;
    const cv=document.createElement('canvas'); cv.width=W; cv.height=H;
    const ctx=cv.getContext('2d'); ctx.drawImage(img,0,0,W,H);
    const px=ctx.getImageData(0,0,W,H).data;
    const N=W*H;
    const cov=new Float32Array(N), col=new Float32Array(N*3);
    for(let i=0;i<N;i++){ cov[i]=px[i*4+3]/255; col[i*3]=px[i*4]/255; col[i*3+1]=px[i*4+1]/255; col[i*3+2]=px[i*4+2]/255; }
    const covB=boxBlur(cov,W,H,1);
    const rCh=new Float32Array(N),gCh=new Float32Array(N),bCh=new Float32Array(N);
    for(let i=0;i<N;i++){ rCh[i]=col[i*3]; gCh[i]=col[i*3+1]; bCh[i]=col[i*3+2]; }
    const rB=boxBlur(rCh,W,H,2), gB=boxBlur(gCh,W,H,2), bB=boxBlur(bCh,W,H,2);
    const gx=new Float32Array(N), gy=new Float32Array(N);
    const at=(x,y)=>covB[Math.min(H-1,Math.max(0,y))*W+Math.min(W-1,Math.max(0,x))];
    for(let y=0;y<H;y++)for(let x=0;x<W;x++){ const i=y*W+x;
      gx[i]=(at(x+1,y-1)+2*at(x+1,y)+at(x+1,y+1))-(at(x-1,y-1)+2*at(x-1,y)+at(x-1,y+1));
      gy[i]=(at(x-1,y+1)+2*at(x,y+1)+at(x+1,y+1))-(at(x-1,y-1)+2*at(x,y-1)+at(x+1,y-1)); }
    let Jxx=new Float32Array(N),Jxy=new Float32Array(N),Jyy=new Float32Array(N);
    for(let i=0;i<N;i++){ Jxx[i]=gx[i]*gx[i]; Jxy[i]=gx[i]*gy[i]; Jyy[i]=gy[i]*gy[i]; }
    for(let p=0;p<4;p++){ Jxx=boxBlur(Jxx,W,H,4); Jxy=boxBlur(Jxy,W,H,4); Jyy=boxBlur(Jyy,W,H,4); }
    const dirx=new Float32Array(N), diry=new Float32Array(N);
    for(let i=0;i<N;i++){ const a=Jxx[i],b=Jxy[i],d=Jyy[i];
      const fa=0.5*Math.atan2(2*b,(a-d))+Math.PI/2; dirx[i]=Math.cos(fa); diry[i]=Math.sin(fa); }
    const align=(i,j)=>{ if(dirx[i]*dirx[j]+diry[i]*diry[j]<0){ dirx[i]=-dirx[i]; diry[i]=-diry[i]; } };
    for(let pass=0;pass<2;pass++) for(let y=0;y<H;y++)for(let x=0;x<W;x++){ const i=y*W+x; if(x>0)align(i,i-1); if(y>0)align(i,i-W); }
    for(let i=0;i<N;i++){ if(dirx[i]<0){ dirx[i]=-dirx[i]; diry[i]=-diry[i]; } }

    const eligible=[];
    for(let i=0;i<N;i++) if(cov[i]>0.35) eligible.push(i);
    const roots=[]; const want=cfg.hairs;
    for(let k=0;k<want;k++){ const i=eligible[(Math.random()*eligible.length)|0];
      if(cov[i]<0.35) continue; const x=i%W, y=(i/W)|0;
      roots.push({i, x:x+Math.random()-0.5, y:y+Math.random()-0.5}); }

    const sampleFlow=(x,y)=>{ const xi=Math.min(W-1,Math.max(0,x|0)), yi=Math.min(H-1,Math.max(0,y|0)); const j=yi*W+xi; return [dirx[j],diry[j]]; };
    const sampleCov=(x,y)=>{ const xi=Math.min(W-1,Math.max(0,x|0)), yi=Math.min(H-1,Math.max(0,y|0)); return covB[yi*W+xi]; };

    const worldW=W/H, worldH=1.0;
    const n=roots.length;
    const iRoot=new Float32Array(n*2), iDir=new Float32Array(n*2), iLen=new Float32Array(n),
          iWid=new Float32Array(n), iCol=new Float32Array(n*3), iSeed=new Float32Array(n), iPhase=new Float32Array(n);
    const px2wx=x=>(x/W-0.5)*worldW, py2wy=y=>(0.5-y/H)*worldH;
    for(let k=0;k<n;k++){ const r=roots[k]; let dx=dirx[r.i], dy=diry[r.i];
      let pxx=r.x, pyy=r.y, L=0, pdx=dx, pdy=dy; const STEP=1.6, MAXS=70;
      for(let s=0;s<MAXS;s++){ let [fx,fy]=sampleFlow(pxx,pyy); if(fx*pdx+fy*pdy<0){fx=-fx;fy=-fy;} pdx=fx;pdy=fy;
        pxx-=fx*STEP; pyy-=fy*STEP; if(sampleCov(pxx,pyy)<0.28) break; L+=STEP; }
      iRoot[k*2]=px2wx(r.x); iRoot[k*2+1]=py2wy(r.y);
      const dl=Math.hypot(dx,dy)||1; iDir[k*2]=dx/dl; iDir[k*2+1]=-dy/dl;
      const rnd=Math.random(); iLen[k]=0.013+0.012*rnd; iWid[k]=0.0026+0.0018*Math.random();
      const c=orangeClamp(rB[r.i],gB[r.i],bB[r.i]); iCol[k*3]=c[0]; iCol[k*3+1]=c[1]; iCol[k*3+2]=c[2];
      iSeed[k]=Math.random()*6.283; iPhase[k]=L/Math.max(W,H); }

    const baseCanvas=document.createElement('canvas'); baseCanvas.width=W; baseCanvas.height=H;
    const bctx=baseCanvas.getContext('2d'); const bimg=bctx.createImageData(W,H); const bd=bimg.data;
    for(let i=0;i<N;i++){ const a=smooth01(cov[i],0.45,0.72); const c=orangeClamp(rB[i],gB[i],bB[i]);
      bd[i*4]=c[0]*255; bd[i*4+1]=c[1]*255; bd[i*4+2]=c[2]*255; bd[i*4+3]=a*255; }
    bctx.putImageData(bimg,0,0);
    return { count:n, worldW, worldH, baseCanvas, iRoot,iDir,iLen,iWid,iCol,iSeed,iPhase };
  }

  function baseGeometry(){ const v=[];
    for(let s=0;s<SEGMENTS;s++){ const t0=s/SEGMENTS, t1=(s+1)/SEGMENTS;
      v.push(t0,-1,0, t1,-1,0, t1,1,0, t0,-1,0, t1,1,0, t0,1,0); }
    return new Float32Array(v); }

  // ---- build + run -----------------------------------------------------
  function build(){
    const transparent = cfg.background === 'transparent';
    renderer = new THREE.WebGLRenderer({canvas, antialias:true, alpha:transparent});
    renderer.setPixelRatio(Math.min(window.devicePixelRatio||1, 2));
    if (transparent) renderer.setClearAlpha(0);
    else renderer.setClearColor(new THREE.Color(cfg.background), 1);

    scene = new THREE.Scene();

    baseTex = new THREE.CanvasTexture(data.baseCanvas);
    baseTex.minFilter = THREE.LinearFilter; baseTex.magFilter = THREE.LinearFilter;
    const baseMat = new THREE.MeshBasicMaterial({map:baseTex, transparent:true, depthTest:false, depthWrite:false});
    basePlane = new THREE.Mesh(new THREE.PlaneGeometry(data.worldW, data.worldH), baseMat);
    basePlane.renderOrder = 0; scene.add(basePlane);

    geo = new THREE.InstancedBufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(baseGeometry(),3));
    geo.setAttribute('iRoot', new THREE.InstancedBufferAttribute(data.iRoot,2));
    geo.setAttribute('iDir',  new THREE.InstancedBufferAttribute(data.iDir,2));
    geo.setAttribute('iLen',  new THREE.InstancedBufferAttribute(data.iLen,1));
    geo.setAttribute('iWid',  new THREE.InstancedBufferAttribute(data.iWid,1));
    geo.setAttribute('iCol',  new THREE.InstancedBufferAttribute(data.iCol,3));
    geo.setAttribute('iSeed', new THREE.InstancedBufferAttribute(data.iSeed,1));
    geo.setAttribute('iPhase',new THREE.InstancedBufferAttribute(data.iPhase,1));
    geo.instanceCount = Math.max(1, Math.round(data.count * cfg.density));

    mat = new THREE.ShaderMaterial({ uniforms, vertexShader:VERT, fragmentShader:FRAG,
      transparent:true, depthTest:false, depthWrite:false, blending:THREE.NormalBlending });
    mesh = new THREE.Mesh(geo, mat); mesh.frustumCulled=false; mesh.renderOrder=1; scene.add(mesh);

    camera = new THREE.OrthographicCamera(-1,1,1,-1,-10,10);
    resize();

    ro = new ResizeObserver(resize); ro.observe(container);
    if (cfg.pauseWhenOffscreen && 'IntersectionObserver' in window) {
      io = new IntersectionObserver(es=>{ visible = es[0].isIntersecting; if(visible && !raf) loop(); }, {threshold:0});
      io.observe(container);
    }
    if (cfg.interactive) {
      container.addEventListener('pointermove', onMove);
      container.addEventListener('pointerdown', onMove);
      container.addEventListener('pointerleave', onLeave);
    }
    built = true; last = performance.now(); loop();
  }

  function resize(){
    if (!renderer) return;
    const w = container.clientWidth || 1, h = container.clientHeight || 1;
    renderer.setSize(w,h,false);
    const pad=1.12, tAR=w/h, cAR=data.worldW/data.worldH;
    let halfW, halfH;
    if (tAR>cAR){ halfH=data.worldH*0.5*pad; halfW=halfH*tAR; }
    else { halfW=data.worldW*0.5*pad; halfH=halfW/tAR; }
    camera.left=-halfW; camera.right=halfW; camera.top=halfH; camera.bottom=-halfH;
    camera.updateProjectionMatrix(); camera._halfW=halfW; camera._halfH=halfH;
    if (ring){ const d=uniforms.uRadius.value*(h/halfH); ring.style.width=d+'px'; ring.style.height=d+'px'; }
  }

  function toWorld(clientX, clientY){
    const rect = renderer.domElement.getBoundingClientRect();
    const x = ((clientX-rect.left)/rect.width)*2-1;
    const y = -(((clientY-rect.top)/rect.height)*2-1);
    return {x:x*camera._halfW, y:y*camera._halfH};
  }
  function onMove(e){
    if (!camera) return;
    const w = toWorld(e.clientX, e.clientY);
    if (Math.abs(uniforms.uMouseOn.value) < 0.04){ uniforms.uMouse.value.set(w.x,w.y); combVel=0; }
    mTX=w.x; mTY=w.y; mOn=1;
    if (ring){ ring.style.left=e.clientX+'px'; ring.style.top=e.clientY+'px'; ring.style.opacity='1'; }
  }
  function onLeave(){ mOn=0; if(ring) ring.style.opacity='0'; }

  function loop(){
    if (disposed) return;
    if (!visible){ raf=null; return; }
    raf = requestAnimationFrame(loop);
    const now=performance.now(), dt=Math.min(0.05,(now-last)/1000); last=now;
    uniforms.uTime.value += dt;
    const posK = 1 - Math.exp(-dt*10);
    uniforms.uMouse.value.x += (mTX - uniforms.uMouse.value.x)*posK;
    uniforms.uMouse.value.y += (mTY - uniforms.uMouse.value.y)*posK;
    const T=mOn, K = T>0.5 ? COMB_K : COMB_K_RELEASE, c = 2*combZeta*Math.sqrt(K);
    const steps=Math.max(1,Math.ceil(dt/0.016)), h=dt/steps;
    for(let s=0;s<steps;s++){ const x=uniforms.uMouseOn.value;
      combVel += (-K*(x-T) - c*combVel)*h; uniforms.uMouseOn.value = x + combVel*h; }
    renderer.render(scene,camera);
  }

  // ---- boot ------------------------------------------------------------
  const img = new Image();
  img.crossOrigin = 'anonymous';
  img.onload = () => { if (disposed) return; try { data = preprocess(img); build(); } catch(e){ console.error('[hairLettering]', e); } };
  img.onerror = () => console.error('[hairLettering] image failed to load');
  img.src = cfg.imageUrl || EMBEDDED_IMAGE;

  // ---- public API ------------------------------------------------------
  return {
    // pause/resume the render loop (frees GPU/CPU when the hero is hidden)
    pause(){ visible = false; if (raf){ cancelAnimationFrame(raf); raf = null; } },
    resume(){ if (!visible){ visible = true; if (!raf && built) loop(); } },
    // live-tune while running (handy during the tweak phase)
    set(partial={}){
      if ('movement' in partial) uniforms.uWind.value = partial.movement;
      if ('hairLength' in partial) uniforms.uLen.value = partial.hairLength;
      if ('combStrength' in partial) uniforms.uComb.value = partial.combStrength;
      if ('combSize' in partial) uniforms.uRadius.value = 0.04 + partial.combSize*0.42;
      if ('bounce' in partial) combZeta = 1.15 - partial.bounce*1.0;
      if ('mode' in partial) uniforms.uMode.value = partial.mode==='flow'?1:0;
      if ('density' in partial && geo) geo.instanceCount = Math.max(1, Math.round(data.count*partial.density));
    },
    destroy(){
      disposed = true;
      if (raf) cancelAnimationFrame(raf), raf=null;
      if (ro) ro.disconnect();
      if (io) io.disconnect();
      if (cfg.interactive){
        container.removeEventListener('pointermove', onMove);
        container.removeEventListener('pointerdown', onMove);
        container.removeEventListener('pointerleave', onLeave);
      }
      if (built){
        geo.dispose(); mat.dispose(); baseTex.dispose();
        basePlane.geometry.dispose(); basePlane.material.dispose();
        renderer.dispose();
      }
      if (canvas.parentNode) canvas.parentNode.removeChild(canvas);
      if (ring && ring.parentNode) ring.parentNode.removeChild(ring);
    }
  };
}

export default createHairLettering;
